            _q(16, 9, 'application', 'Khi vẽ cảnh phố phường quê em hiện đại (với con đường sạch đẹp, hàng cây xanh, ngôi nhà mới), chi tiết nào nhắc nhở về văn minh giao thông?', 'Các phương tiện đi đúng làn đường, người đi bộ đi trên vỉa hè hoặc vạch kẻ qua đường', ['Ô tô chạy leo lên mái nhà', 'Các bạn nhỏ đứng giữa lòng đường chơi bóng đá', 'Xe máy đi ngược chiều lên vỉa hè'],
               'Đưa nét đẹp văn hóa giao thông vào tranh sinh hoạt rất ý nghĩa.', 'Mĩ thuật & Đời sống'),
            _q(16, 10, 'application', 'Để bức tranh quê hương có chiều sâu (không bị phẳng lì như dán nhãn), ta vẽ kích thước các bạn nhỏ đứng ở gần và các bạn đứng đằng xa thế nào?', 'Các bạn đứng gần (tiền cảnh) vẽ to rõ hơn; các bạn ở xa (hậu cảnh) vẽ nhỏ hơn và cao hơn chút trên trang giấy', ['Vẽ các bạn ở xa to gấp đôi bạn ở gần', 'Vẽ tất cả mọi người bằng đúng một cỡ chiều cao', 'Đặt tất cả mọi người chồng lên một điểm'],
               'Chênh lệch kích thước gần to – xa nhỏ tạo cảm giác không gian rộng mở.', 'Luật xa gần đơn giản'),
            _q(16, 11, 'application', 'Bảng so sánh chủ đề tranh phong cảnh và tranh sinh hoạt ngày hội: Điểm khác nhau chính ở nhân vật là gì?', 'Tranh phong cảnh tập trung thiên nhiên (cây, núi, sông); tranh ngày hội nhấn mạnh con người vui chơi hoạt động', ['Tranh phong cảnh không được dùng màu xanh lá', 'Tranh ngày hội không được có bầu trời', 'Cả hai không bao giờ vẽ cây cối'],
               'Hiểu rõ trọng tâm đề tài giúp chọn bố cục hợp lí ngay từ đầu.', 'Phân biệt đề tài',
               fig=table_fig('So sánh hai đề tài', ['Đề tài', 'Trọng tâm chính'], [['Tranh phong cảnh', 'Trời, sông, núi'], ['Tranh ngày hội', 'Vui chơi, cờ hoa'], ['Đề tài gia đình', 'Bố mẹ, con sum họp'], ['Đề tài trường em', 'Thầy cô, lớp học']])),
            _q(16, 12, 'application', 'Khi tô màu nền bầu trời hay bãi cỏ rộng của tranh phong cảnh, ta nên đưa nét sáp màu theo chiều nào để mặt giấy mịn mượt nhất?', 'Đưa nét ngang hoặc hơi chéo đều tay nhẹ nhàng liên tục', ['Tô thẳng đứng chỗ này rồi quay ngang chỗ kia lởm chởm', 'Chấm từng dấu chấm rời rạc cách nhau 3 cm', 'Cầm bút sáp gõ lộc cộc xuống mặt giấy'],
               'Đưa màu nền đều hướng tạo mảng không gian êm dịu tôn các nhân vật chính.', 'Kĩ thuật tô nền'),
            _q(16, 13, 'advanced', 'Một nhóm học sinh lớp 1 cùng thực hiện bức tranh tập thể khổ lớn "Quê hương tươi đẹp" (mỗi bạn vẽ, cắt dán một góc rồi ghép chung). Điều gì quan trọng nhất để cả bức tranh lớn hài hòa?', 'Cả nhóm bàn bạc thống nhất trước ý tưởng chung (bên nào là sông, đâu là nhà, nền trời màu gì) để các phần ăn khớp với nhau', ['Mỗi bạn vẽ một kiểu hoàn toàn trái ngược không hỏi nhau', 'Cả nhóm tranh nhau tô cùng một chỗ giữa tờ giấy', 'Một bạn làm hết còn các bạn khác ngồi chơi'],
               'Phân công rõ ràng và thống nhất tông nền giúp tranh tập thể gắn kết thành một khối đẹp.', 'Làm việc nhóm'),
            _q(16, 14, 'advanced', 'Ở một bức tranh rước đèn Trung thu, bạn Tuấn vẽ 3 hàng rước đèn, mỗi hàng có 5 bạn nhỏ cầm đèn ông sao. Có bao nhiêu bạn nhỏ đang rước đèn trong tranh của Tuấn?', '15 bạn nhỏ', ['8 bạn nhỏ', '12 bạn nhỏ', '20 bạn nhỏ'],
               '3 × 5 = 15 bạn nhỏ.', 'Toán & Quan sát'),
